import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import Button from 'flarum/common/components/Button';
import PagesListItem from './PagesListItem';

/**
 * The `PagesList` component displays a list of Pages.
 *
 */
export default class PagesList extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    /**
     * Whether or not pages results are loading.
     *
     * @type {Boolean}
     */
    this.loading = true;

    /**
     * The pages in the pages list.
     *
     * @type {Page}
     */
    this.pages = [];

    /**
     * Current page number.
     *
     * @type {Integer}
     */
    this.page = 0;

    /**
     * The number of activity items to load per request.
     *
     * @type {Integer}
     */
    this.loadLimit = 20;
    this.refresh();
  }
  view() {
    if (this.loading) {
      return m("div", {
        className: "PageList-loading"
      }, LoadingIndicator.component());
    }
    if (this.pages.length === 0) {
      const text = app.translator.trans('fof-pages.admin.pages_list.empty_text');
      return Placeholder.component({
        text
      });
    }
    let next, prev;
    if (this.nextResults === true) {
      next = Button.component({
        className: 'Button Button--PageList-next',
        icon: 'fas fa-angle-right',
        onclick: this.loadNext.bind(this)
      });
    }
    if (this.prevResults === true) {
      prev = Button.component({
        className: 'Button Button--PageList-prev',
        icon: 'fas fa-angle-left',
        onclick: this.loadPrev.bind(this)
      });
    }
    return m("div", {
      className: "PageList"
    }, m("table", {
      className: "PageList-results"
    }, m("thead", null, m("tr", null, m("th", null, app.translator.trans('fof-pages.admin.pages_list.title')), m("th", null))), m("tbody", null, this.pages.map(page => {
      return PagesListItem.component({
        page
      });
    }))), m("div", {
      className: "PageList-pagination"
    }, next, prev));
  }

  /**
   * @public
   */
  refresh(clear) {
    if (clear === void 0) {
      clear = true;
    }
    if (clear) {
      this.loading = true;
      this.pages = [];
    }
    return this.loadResults().then(this.parseResults.bind(this));
  }

  /**
   * Load a new page of Pages results.
   *
   * @param {Integer} page number.
   * @return {Promise}
   */
  loadResults() {
    const offset = this.page * this.loadLimit;
    return app.store.find('pages', {
      page: {
        offset,
        limit: this.loadLimit
      }
    });
  }

  /**
   * Load the next page of results.
   *
   * @public
   */
  loadNext() {
    if (this.nextResults === true) {
      this.page++;
      this.refresh();
    }
  }

  /**
   * Load the previous page of results.
   *
   * @public
   */
  loadPrev() {
    if (this.prevResults === true) {
      this.page--;
      this.refresh();
    }
  }

  /**
   * Parse results and append them to the page list.
   *
   * @param {Page[]} results
   * @return {Page[]}
   */
  parseResults(results) {
    [].push.apply(this.pages, results);
    this.loading = false;
    this.nextResults = !!results.payload.links.next;
    this.prevResults = !!results.payload.links.prev;
    m.redraw();
    return results;
  }
}
flarum.reg.add('fof-pages', 'admin/components/PagesList', PagesList);